import { backendCommands, frontendCommands } from './commands.js';

/** "4.2" -> "4.2.x", "4" -> "4.x", "3.5.7" -> "3.5.7" (exact version entered). */
const bootBranch = (v) => (/^\d+\.\d+\.\d+/.test(v) ? v : `${v}.x`);

const keep = (lines) => lines.filter((l) => l !== false && l != null);

// Spring Initializr ids (https://start.spring.io, `dependencies` field).
function initializrDependencies(a) {
  const b = a.backend;
  const ops = a.ops ?? {};
  const deps = ['web', 'validation', 'actuator', 'configuration-processor'];
  deps.push({ jpa: 'data-jpa', jdbc: 'data-jdbc', jooq: 'jooq' }[b.persistence]);
  deps.push(b.database);
  if (b.migration !== 'none') deps.push(b.migration);
  if (b.libs.includes('lombok')) deps.push('lombok');
  if (b.libs.includes('security')) deps.push('security');
  if (b.libs.includes('testcontainers')) deps.push('testcontainers');
  if (ops.compose) deps.push('docker-compose');
  if (ops.observability?.includes('prometheus')) deps.push('prometheus');
  if (ops.sessions === 'redis') deps.push('data-redis', 'session-data-redis');
  if (ops.scheduling === 'quartz') deps.push('quartz');
  return deps;
}

/** What Initializr does not provide: Claude adds it after generation. */
function backendExtras(a) {
  const b = a.backend;
  const ops = a.ops ?? {};
  const maven = b.build === 'maven';
  const has = (l) => b.libs.includes(l);
  return keep([
    has('springdoc') &&
      `- **springdoc-openapi**: \`org.springdoc:springdoc-openapi-starter-webmvc-ui\`, in the version compatible with Spring Boot ${bootBranch(b.springBoot)} (check the compatibility matrix on springdoc.org).`,
    has('mapstruct') &&
      `- **MapStruct**: \`org.mapstruct:mapstruct\` + the \`mapstruct-processor\` annotation processor${has('lombok') ? ', with `lombok-mapstruct-binding` and Lombok declared **before** MapStruct in the processors' : ''}.`,
    has('archunit') &&
      '- **ArchUnit**: `com.tngtech.archunit:archunit-junit5` in test scope, plus a first test encoding the architecture rules from the backend `CLAUDE.md`.',
    b.formatter === 'spotless' &&
      `- **Spotless**: ${maven ? '`com.diffplug.spotless:spotless-maven-plugin`' : '`com.diffplug.spotless`'} plugin with palantir-java-format, then run \`${backendCommands(b).format}\` once.`,
    b.formatter === 'checkstyle' && `- **Checkstyle**: ${maven ? '`maven-checkstyle-plugin`' : '`checkstyle`'} plugin with a basic configuration.`,
    a.deploy?.container === 'jib' &&
      `- **Jib**: ${maven ? '`com.google.cloud.tools:jib-maven-plugin`' : '`com.google.cloud.tools.jib`'} plugin, JRE ${b.java} base image.`,
    ops.scheduling === 'shedlock' &&
      '- **ShedLock**: `net.javacrumbs.shedlock:shedlock-spring` + `shedlock-provider-jdbc-template`, `@EnableSchedulerLock`, and the `shedlock` table created by a migration.',
  ]);
}

function backendConfig(a) {
  const b = a.backend;
  const ops = a.ops ?? {};
  const obs = ops.observability ?? [];
  const k8s = ops.orchestrator && ops.orchestrator !== 'none';
  const tool = b.migration;
  return keep([
    '- Replace `application.properties` with `application.yml`.',
    b.persistence === 'jpa' && '- `spring.jpa.open-in-view: false`, `spring.jpa.hibernate.ddl-auto: validate`.',
    tool === 'liquibase' &&
      `- Create the master changelog \`src/main/resources/db/changelog/db.changelog-master.${b.liquibaseFormat === 'xml' ? 'xml' : 'yaml'}\` including the \`changes/\` directory (\`includeAll\`), otherwise the application will not start.`,
    tool === 'flyway' && '- Create the `src/main/resources/db/migration/` directory.',
    k8s && '- `server.shutdown: graceful` and `management.endpoint.health.probes.enabled: true`.',
    (obs.includes('loki') || obs.includes('elk')) && '- Structured logs: `logging.structured.format.console: ecs` (or `logstash`).',
    (ops.migrationRun === 'job' || ops.migrationRun === 'init') &&
      `- Deployment profile (e.g. \`application-k8s.yml\`) with \`spring.${tool}.enabled: false\`: migrations run outside the application there.`,
    '- Create the packages of the chosen architecture (see the backend `CLAUDE.md`), with a `package-info.java` in each.',
    ops.compose && '- Check the `compose.yaml` generated by Initializr (database) and add any missing services.',
  ]);
}

function backendSection(a) {
  const b = a.backend;
  const dir = a.project.dirs.backend;
  const cmd = backendCommands(b);
  const pkg = b.basePackage;
  const groupId = pkg.includes('.') ? pkg.split('.').slice(0, -1).join('.') : pkg;
  const artifactId = a.project.name.toLowerCase().replace(/[^a-z0-9-]/g, '-');
  const type = b.build === 'maven' ? 'maven-project' : 'gradle-project-kotlin';
  const buildFile = b.build === 'maven' ? 'pom.xml' : 'build.gradle.kts';
  const extras = backendExtras(a);

  return keep([
    '## Spring Boot backend',
    '',
    `Skip this part if \`${dir === '.' ? '' : `${dir}/`}${buildFile}\` already exists.`,
    '',
    '### 1. Pick the Spring Boot version',
    '',
    'Read the versions offered by Initializr:',
    '',
    '```bash',
    "curl -sS --fail-with-body https://start.spring.io -H 'Accept: application/json'",
    '```',
    '',
    `In \`bootVersion.values\`, take the \`id\` of the **latest GA release of the ${bootBranch(b.springBoot)} line** (no SNAPSHOT, M or RC), as is. Check in \`javaVersion.values\` that Java ${b.java} is offered.`,
    '',
    `**If no ${bootBranch(b.springBoot)} version is offered** (Initializr only keeps recent lines): stop and ask the user whether the oldest available line is acceptable. Do not generate and then downgrade versions by hand.`,
    '',
    '### 2. Generate with Spring Initializr',
    '',
    '```bash',
    'curl -sS --fail-with-body https://start.spring.io/starter.zip \\',
    `  -d type=${type} -d language=java \\`,
    '  -d bootVersion=<VERSION_FROM_STEP_1> \\',
    `  -d javaVersion=${b.java} \\`,
    `  -d groupId=${groupId} -d artifactId=${artifactId} -d name=${artifactId} \\`,
    `  -d packageName=${pkg} \\`,
    `  -d dependencies=${initializrDependencies(a).join(',')} \\`,
    '  -o "${TMPDIR:-/tmp}/backend-bootstrap.zip"',
    `unzip -n "\${TMPDIR:-/tmp}/backend-bootstrap.zip" -d ${dir}`,
    '```',
    '',
    'If Initializr rejects a dependency id, fix it using `dependencies.values` from the step 1 metadata (do not silently drop it).',
    '',
    '### 3. Add what Initializr does not provide',
    '',
    'For every dependency or plugin: **look up the latest stable version on Maven Central**, never write a version from memory.',
    '',
    ...(extras.length ? extras : ['- Nothing to add.']),
    '',
    '### 4. Configure',
    '',
    ...backendConfig(a),
    '',
    '### 5. Verify',
    '',
    `- Run \`${cmd.verify}\`${dir === '.' ? '' : ` from \`${dir}/\``}: the build and tests must pass.`,
    b.libs.includes('testcontainers') && '- Testcontainers tests need Docker: if it is not running, say so instead of disabling the tests.',
    '',
  ]);
}

function frontendSection(a) {
  const f = a.frontend;
  const dir = a.project.dirs.frontend;
  const cmd = frontendCommands(f);
  const name = a.project.name.toLowerCase().replace(/[^a-z0-9-]/g, '-');
  const add = (pkg) => `\`${cmd.exec} ng add ${pkg}\``;
  const spec = a.backend ? 'http://localhost:8080/v3/api-docs' : f.apiSpec;

  return keep([
    '## Angular frontend',
    '',
    `Skip this part if \`${dir === '.' ? '' : `${dir}/`}angular.json\` already exists.`,
    '',
    '### 1. Generate with the Angular CLI',
    '',
    `First read the available options: \`npx -y @angular/cli@${f.angular} new --help\`.`,
    '',
    'Generate in a temporary directory (the repository already contains files), then copy without overwriting anything:',
    '',
    '```bash',
    `cd "\${TMPDIR:-/tmp}" && npx -y @angular/cli@${f.angular} new ${name} \\`,
    '  --routing --style=scss --ssr=false --skip-git --skip-install \\',
    `  --package-manager=${f.packageManager}`,
    `rsync -a --ignore-existing "\${TMPDIR:-/tmp}/${name}/" <repository-root>/${dir === '.' ? '' : `${dir}/`}`,
    '```',
    '',
    `- If the CLI offers a test runner option, choose **${{ vitest: 'Vitest', jest: 'Jest', karma: 'Karma' }[f.unitTests]}**.`,
    '- If the CLI offers to generate an AI assistant configuration, decline: the rules are already in `CLAUDE.md`.',
    `- Then, in \`${dir}\`: \`${f.packageManager} install\`.`,
    '',
    '### 2. Complete',
    '',
    f.ui.includes('material') && `- Angular Material: ${add('@angular/material')}.`,
    f.ui.includes('primeng') && '- PrimeNG: follow the official installation guide (primeng.org) for the Angular version in use.',
    f.ui.includes('tailwind') && '- Tailwind CSS: follow the official Angular guide on tailwindcss.com.',
    f.state === 'signalstore' && `- NgRx SignalStore: ${add('@ngrx/signals')}.`,
    f.state === 'ngrx' && `- NgRx: ${add('@ngrx/store')}, ${add('@ngrx/effects')}, ${add('@ngrx/store-devtools')}.`,
    f.unitTests === 'jest' && '- Jest: replace the default runner if the CLI did not offer it (official Jest builder or `jest-preset-angular`).',
    f.e2e === 'playwright' &&
      `- Playwright: \`${f.packageManager === 'npm' ? 'npm init playwright@latest' : `${f.packageManager} create playwright`}\`, tests in \`e2e/\`.`,
    f.e2e === 'cypress' && `- Cypress: ${add('@cypress/schematic')}.`,
    f.lint && `- Lint: ${add('angular-eslint')}, then Prettier + \`eslint-config-prettier\`; \`lint\` script in \`package.json\`.`,
    f.apiClient === 'generated' &&
      `- API client: \`@openapitools/openapi-generator-cli\` as a devDependency, \`${f.apiScript}\` script (\`typescript-angular\` generator, input \`${spec}\`, output \`${f.apiDir}\`).`,
    a.backend && '- `proxy.conf.json` forwarding `/api` to `http://localhost:8080` in development, referenced in `angular.json`.',
    '- Create `src/app/core/`, `src/app/shared/` and `src/app/features/`.',
    '',
    '### 3. Verify',
    '',
    `- \`${cmd.test}\`, ${cmd.lint ? `\`${cmd.lint}\`, ` : ''}\`${cmd.build}\` must pass${dir === '.' ? '' : ` from \`${dir}/\``}.`,
    '',
  ]);
}

function deploySection(a) {
  const d = a.deploy;
  const ops = a.ops;
  const k8s = ops.orchestrator !== 'none';
  const dir = a.project.dirs.deploy;
  return keep([
    '## Deployment',
    '',
    `Only create what is missing in \`${dir === '.' ? '.' : `${dir}/`}\`, following the deployment \`CLAUDE.md\`.`,
    '',
    d.container === 'dockerfile' && a.project.layout !== 'infra' && '- One multi-stage Dockerfile per application (build, then a minimal runtime image, non-root user).',
    k8s && d.packaging === 'helm' && '- Helm chart: `helm create`, then clean up the sample chart; one `values-<env>.yaml` per environment.',
    k8s && d.packaging === 'kustomize' && '- Kustomize: `base/` + `overlays/<env>/` for each environment.',
    k8s && ops.ha && '- Apply the high-availability rules right away (replicas, probes, PDB, `topologySpreadConstraints`, resources).',
    k8s && ops.migrationRun === 'job' && '- Migration Job run before the rollout (Helm `pre-upgrade` hook or Argo CD `PreSync`).',
    ops.ci !== 'none' && '- Minimal CI pipeline: build + tests for each application, then image build.',
    '- Check with `helm lint` / `helm template` or `kubectl kustomize` as appropriate: **never deploy anything to a cluster**.',
    '',
  ]);
}

export function bootstrapCommand(a) {
  const { parts } = a.project;
  const sections = [];
  if (parts.includes('backend')) sections.push(...backendSection(a));
  if (parts.includes('frontend')) sections.push(...frontendSection(a));
  if (parts.includes('deploy')) sections.push(...deploySection(a));

  const tools = [
    'Bash(curl -sS --fail-with-body https://start.spring.io:*)',
    'Bash(unzip -n:*)',
    'Bash(rsync -a --ignore-existing:*)',
    a.frontend && `Bash(npx -y @angular/cli@${a.frontend.angular}:*)`,
  ].filter(Boolean);

  const generators = [
    parts.includes('backend') && 'Spring Initializr',
    parts.includes('frontend') && 'Angular CLI',
    parts.includes('deploy') && 'deployment',
  ].filter(Boolean);

  return [
    '---',
    `description: Scaffolds the project skeleton (${generators.join(', ')})`,
    `argument-hint: "[${parts.join('|')}] (empty = everything)"`,
    'disable-model-invocation: true',
    `allowed-tools: ${tools.join(', ')}`,
    '---',
    '',
    `# Bootstrap ${a.project.name}`,
    '',
    'Parts to scaffold: `$ARGUMENTS` (if empty: every part below, in order).',
    '',
    '## Rules',
    '',
    '- **Never overwrite an existing file.** If a part is already scaffolded, skip it and say so.',
    '- Use the official generators; never write a complete build file by hand.',
    '- **No version from memory**: Spring Boot versions from Initializr, dependency versions from Maven Central or npm.',
    '- Follow the conventions in the project’s `CLAUDE.md` files (package, architecture, naming, migrations).',
    '- At the end of each part, run the listed verification and fix issues before moving on.',
    '- Finish with a summary (what was created, what is left to do) and suggest one commit per part, without committing.',
    '',
    ...sections,
  ].join('\n');
}
